#!/usr/bin/env bash
set -euo pipefail
cd "$HOME/PFMP" || exit 1

DEPLOYMENT_ID="AKfycby6ykCxTxhUjq8FeKoBzgEMj6xzdrjXnBFgOt-1pAw1GfkaAigWMH7jj0EIg_BWpEkmxg"
LABEL="PFMP v1.0.0-dev.147"
PAGE="apps-script/Admin_Conventions_PFMP.html"

STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="backup_avant_DEV147_${STAMP}"
mkdir -p "$BACKUP"
cp "$PAGE" "$BACKUP/"

echo "" | base64 -d > /tmp/dev147_patch.py
python3 /tmp/dev147_patch.py

echo "=== CONTROLES DEV.147 ==="
grep -q "Validation en cours" "$PAGE"
grep -q "Annulation en cours" "$PAGE"
grep -q "Interruption en cours" "$PAGE"
grep -q 'id="confirmModal"' "$PAGE"
grep -q "function askConfirm" "$PAGE"
grep -q "selectedYoung" "$PAGE"

python3 - <<'PY'
from pathlib import Path
import re
s=Path("apps-script/Admin_Conventions_PFMP.html").read_text(encoding="utf-8")
scripts=re.findall(r"<script>(.*?)</script>",s,re.S)
js="\n".join(scripts)
js=re.sub(r"<\?!=.*?\?>","{}",js)
Path("/tmp/Admin_Conventions_PFMP_DEV147.js").write_text(js,encoding="utf-8")
PY

node --check /tmp/Admin_Conventions_PFMP_DEV147.js

echo "OK : JavaScript client valide."
echo "OK : identité + feedback + modale présents."

echo "=== PUSH ==="
clasp push -f

echo "=== VERSION ==="
clasp version "$LABEL"

echo "=== DEPLOIEMENT PRINCIPAL ==="
clasp deploy -i "$DEPLOYMENT_ID" -d "$LABEL"

echo "============================================================"
echo " DEV.147 DEPLOYEE AVEC SUCCES"
echo "============================================================"
echo "✓ jeune / classe / période affichés"
echo "✓ boutons bloqués pendant le traitement"
echo "✓ spinner + libellés de traitement"
echo "✓ boîtes système remplacées par une modale intégrée"
echo "✓ push + version + déploiement principal"
echo "============================================================"
